def neighbors(batchsize, n_atoms):
    neighbors = np.array([range(n_atoms)] * n_atoms)
    neighbors = neighbors[~np.eye(neighbors.shape[0], dtype=bool)].reshape(
        neighbors.shape[0], -1
    )[np.newaxis, :]
    return torch.LongTensor(np.repeat(neighbors, batchsize, axis=0))

