def get_sequential_processor():
    def call(name):
        sequential_processor = SequentialProcessor()
        sequential_processor.add(Processor(name))
        return sequential_processor
    return call

def load_image():
    def call(shape, rgb_channel, with_mask=True):
        image = np.ones(shape)
        image[:, :, 0] = rgb_channel[0]
        image[:, :, 1] = rgb_channel[1]
        image[:, :, 2] = rgb_channel[2]
        if with_mask:
            image[10:50, 50:120] = 100
        return image.astype(np.uint8)
    return call

def resized_shape(request):
    def call(image):
        width = int(image.shape[1] * request.param / 100)
        height = int(image.shape[0] * request.param / 100)
        size = width * height * 3
        return (width, height, size)
    return call

