def setUp(self):
        def wrap(func):
            def wrapper(*args):
                if PY3:
                    arg_spec = inspect.getfullargspec(func)
                else:
                    arg_spec = inspect.getargspec(func)
                return func(*args[0:len(arg_spec.args)])

            return wrapper

        def func_with_0_args():
            assert True

        def func_with_1_arg(arg):
            assert arg

        def func_with_2_args(arg1, arg2):
            assert arg1 and arg2

