def loops():
    space = ParameterSpace([ContinuousParameter('x', 0, 1)])

    def make_loop(loop_state):
        gpy_model = GPy.models.GPRegression(loop_state.X, loop_state.Y)
        model = GPyModelWrapper(gpy_model)
        return BayesianOptimizationLoop(space, model)

    return [('GP', make_loop)]

def entropy_search_acquisition(gpy_model, continuous_space):
    sampler = AffineInvariantEnsembleSampler(continuous_space)
    return EntropySearch(gpy_model, continuous_space, sampler, num_representer_points=10)

def continuous_space(n_dims):
    params = [ContinuousParameter('x' + str(i), 0, 1) for i in range(n_dims)]
    return ParameterSpace(params)

def encoding():
    # different types of volcanoes
    return OneHotEncoding(['strato', 'shield', 'dome'])

def simple_square_acquisition():
    class SimpleSquareAcquisition(Acquisition):
        def __init__(self):
            pass

        def evaluate(self, x):
            y = - x[:, 0]**2 + np.sum(x[:, 1:], axis=1) + 1
            return np.atleast_2d(y).T

        @property
        def has_gradients(self):
            return False

    return SimpleSquareAcquisition()

def trust_region_constr_linear_constraint():
    constraints = [LinearInequalityConstraint(np.array([[0, 1]]), np.array([0.5]), np.array([np.inf]))]
    return OptTrustRegionConstrained([(-1, 1), (-1, 1)], constraints, 1000)

def space_2d():
    p1 = ContinuousParameter('c', 1.0, 5.0)
    p2 = ContinuousParameter('d', 1.0, 6.0)

    return ParameterSpace([p1, p2])

def space_3d_mixed():
    p1 = ContinuousParameter('c', 1.0, 5.0)
    p2 = DiscreteParameter('d', [1, 2, 3])
    p3 = CategoricalParameter('cat', OneHotEncoding(['Maine Coon', 'Siamese']))
    return ParameterSpace([p1, p2, p3])

