def ignored_extended_commands():
    ignored_commands = []
    with open(IGNORE_COMMANDS_LOCATION, 'r') as f:
        lines = f.readlines()

        for line in lines:
            line = line.strip()
            if len(line) != 0:
                ignored_commands.append(line.split(', '))

    return ignored_commands

