def client_ctx(request):
    ctx = ssl.create_default_context()
    TRIO_TEST_CA.configure_trust(ctx)
    if request.param in ["default", "tls13"]:
        return ctx
    elif request.param == "tls12":
        ctx.options |= ssl.OP_NO_TLSv1_3
        return ctx
    else:  # pragma: no cover
        assert False

