def records():
    imgs = [np.ones((2, 4, 3), dtype=np.float), np.ones((3, 2, 3), dtype=np.float)]

    records = []
    for img in imgs:
        record = {"img": img}
        record["height"], record["width"], _ = img.shape
        records.append(record)

    return records

