def agent_spec():
    class KeepLaneAgent(Agent):
        def act(self, obs):
            return "keep_lane"

    return AgentSpec(
        interface=AgentInterface.from_type(
            AgentType.Laner, max_episode_steps=MAX_STEPS
        ),
        agent_builder=KeepLaneAgent,
    )

def scenarios(bubbles, num_vehicles):
    with temp_scenario(name="6lane", map="maps/6lane.net.xml") as scenario_root:
        traffic = t.Traffic(
            flows=[
                t.Flow(
                    route=t.Route(
                        begin=("edge-west-WE", lane, 0),
                        end=("edge-east-WE", lane, "max"),
                    ),
                    rate=10,
                    actors={t.TrafficActor(name="car"): 1},
                )
                for lane in range(num_vehicles)
            ]
        )

        gen_scenario(
            t.Scenario(traffic={"all": traffic}, bubbles=bubbles),
            output_dir=scenario_root,
        )

        yield Scenario.variations_for_all_scenario_roots([str(scenario_root)], [])

def scenarios():
    with temp_scenario(name="straight", map="maps/straight.net.xml") as scenario_root:
        ego_missions = [
            # missions of laner and buddha
            t.Mission(t.Route(begin=("west", 0, 30), end=("east", 0, "max"),)),
            t.Mission(t.Route(begin=("west", 0, 40), end=("east", 0, "max"),)),
        ]
        gen_scenario(
            t.Scenario(ego_missions=ego_missions), output_dir=scenario_root,
        )

        yield Scenario.variations_for_all_scenario_roots(
            [str(scenario_root)], [AGENT_1, AGENT_2]
        )

def smarts():
    laner = AgentInterface(max_episode_steps=1000, action=ActionSpaceType.Lane,)
    buddha = AgentInterface(max_episode_steps=1000, action=ActionSpaceType.Lane,)
    agents = {AGENT_1: laner, AGENT_2: buddha}
    smarts = SMARTS(
        agents, traffic_sim=SumoTrafficSimulation(headless=True), envision=None,
    )

    yield smarts
    smarts.destroy()

def scenarios(request):
    with temp_scenario(name="map", map=request.param[0]) as scenario_root:
        mission = t.Mission(
            route=t.Route(begin=("edge-west-WE", 0, 10), end=(request.param[1], 0, 40))
        )
        gen_scenario(
            t.Scenario(ego_missions=[mission]), output_dir=scenario_root,
        )
        yield Scenario.variations_for_all_scenario_roots(
            [str(scenario_root)], [AGENT_ID]
        )

