def fncProj(fncDir):
    """A temporary folder for a single test function,
    with a project folder.
    """
    prjDir = os.path.join(fncDir, "project")
    if os.path.isdir(prjDir):
        shutil.rmtree(prjDir)
    if not os.path.isdir(prjDir):
        os.mkdir(prjDir)
    return prjDir

