def cli_args(openapi_version, request):
    if request.param == "real":
        schema_url = request.getfixturevalue("schema_url")
        args = (schema_url,)
    else:
        app_path = request.getfixturevalue("loadable_flask_app")
        args = (f"--app={app_path}", "/schema.yaml")
    return args

def new_check(request, testdir, cli):
    exception, message = request.param
    module = testdir.make_importable_pyfile(
        hook=f"""
            import schemathesis

            @schemathesis.register_check
            def new_check(response, result):
                raise {exception}
            """
    )
    yield module, message
    reset_checks()
    # To verify that "new_check" is unregistered
    result = cli.run("--help")
    lines = result.stdout.splitlines()
    assert (
        "  -c, --checks [not_a_server_error|status_code_conformance|content_type_conformance|"
        "response_headers_conformance|response_schema_conformance|all]" in lines
    )

def unregister_hooks():
    yield
    schemathesis.hooks.unregister_all()

def _app():
    """A global AioHTTP application with configurable endpoints."""
    return _aiohttp.create_openapi_app(("success", "failure"))

def endpoints(request):
    marker = request.node.get_closest_marker("endpoints")
    if marker:
        if marker.args and marker.args[0] == "__all__":
            endpoints = tuple(item for item in Endpoint.__members__ if item != "all")
        else:
            endpoints = marker.args
    else:
        endpoints = ("success", "failure")
    return endpoints

def reset_app(_app, endpoints):
    def inner(version):
        _aiohttp.reset_app(_app, endpoints, version)

    return inner

