def file_resource():
    class Stream:
        def __init__(self, data):
            self.data = data

        async def data_uri(self):
            return self.data

        async def __aenter__(self):
            return self

        async def __aexit__(
            self,
            exc_type,
            exc,
            exc_tb,
        ) -> None:
            pass

    class FileResource(files.Resource):
        filename = None
        url = None

        def __init__(self, stream_data):
            self._stream = Stream(data=stream_data)

        def stream(self, executor):
            return self._stream

    return FileResource

