def setUp(self):
        def pred_supported(module):
            return isinstance(module, (nn.Conv2d, nn.Linear))

        def pred_not_unsupported(module):
            return not isinstance(module, (nn.BatchNorm2d, nn.BatchNorm3d))

        def pred_requires_grad(module):
            return all(p.requires_grad for p in module.parameters(recurse=False))

        self.pred_supported = pred_supported
        self.pred_not_unsupported = pred_not_unsupported
        self.pred_mix = lambda m: (not pred_requires_grad(m)) or pred_not_unsupported(m)

def doc_with_field_type(field_type):
    class DocCreator(object):
        def create(self):
            doc = Document()
            if field_type == 'text':
                doc.text = 'aaa'
            elif field_type == 'buffer':
                doc.buffer = b'\x01\x02\x03'
            elif field_type == 'blob':
                doc.blob = np.array([1, 1, 1])
            return doc

    return DocCreator()

def groundtruth_with_field_type(field_type):
    class GTCreator(object):
        def create(self):
            gt = Document()
            if field_type == 'text':
                gt.text = 'aaaa'
            elif field_type == 'buffer':
                gt.buffer = b'\x01\x02\x03\04'
            elif field_type == 'blob':
                gt.blob = np.array([1, 1, 1, 1])
            return gt

    return GTCreator()

def doc_groundtruth_pair(doc_with_field_type, groundtruth_with_field_type):
